mapper.select:
select x.target_cd, x.plan_nm, x.due_date
  from () x
 where x.due_date >= #{from}
   and x.plant_cd = #{plantCd}
 order by x.due_date, x.run_id
 limit #{limit}

select m.mwo_no, m.title, m.status, m.down_yn, m.reported_at
  from cms_mwo m
 where m.mwo_type = 'BM'
   and m.status in ('REQ', 'OPEN', 'WIP')
   and m.reported_at >= #{from} and m.reported_at < #{to}
   and m.plant_cd = #{plantCd}
 order by m.down_yn desc, case when m.status = 'WIP' then 1 else 0 end, m.reported_at, m.mwo_id
 limit #{limit}

select e.plant_cd, e.equip_cd, s.state_cat, s.start_at, s.end_at

 order by s.start_at, s.state_log_id
 limit #{limit}
